import { useEffect } from 'react';
import { db, getMeta, setMeta, type StoredOfferNotes } from '@/db/schema.js';
import { useAuth } from '@/features/auth/session.js';
import { t } from '@/i18n/index.js';
import { serverNow } from '@/lib/serverClock.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { momentEndShort } from './countdown.js';
import {
  holdInline,
  inlineHeld,
  inlineMentionDue,
  isMomentOffer,
  noteInlineMention,
  zoneNameIfOther,
} from './moment.js';
import { openOffer } from './offer.js';
import { sendOfferEvent } from './offerEvents.js';
import { canBuyHere, useBilling } from './state.js';
import { useOfferWords } from './useOfferWords.js';
import { noteSellingShown } from './sellingSignals.js';
import styles from './ProOffer.module.css';

/**
 * The AI-limit line's one mention of an open moment offer (moment offer §5
 * M3, §10.1): "Your price: $24.99 for the first year, until Sat 18:00." —
 * the price and its fixed end, never a countdown, never a pop-up, at most
 * once a local day on this device (the line itself is information and is
 * there on every hit). Nothing in the iPhone app, which never holds one.
 */
export function MomentInline(): React.JSX.Element | null {
  const state = useBilling((s) => s.state);
  const accountZone = useAuth((s) => s.user?.timezone);
  const notes = useLiveQuery<StoredOfferNotes | null>(async () => getMeta('offerNotes'), null, []);
  const now = new Date(serverNow());
  const live = canBuyHere(state) ? openOffer(state, now) : undefined;
  const offer = isMomentOffer(live) ? live : undefined;
  const words = useOfferWords(offer);
  // The day's one mention stays for this run of the app once it was made,
  // even though putting it on screen spent it.
  const due = notes !== null && inlineMentionDue(notes, now);
  const shows = offer !== undefined && words !== undefined && (inlineHeld() === offer.id || due);
  const shownId = shows ? offer.id : undefined;

  // A price on screen: no rating request in this run (sellingSignals.ts).
  useEffect(() => {
    if (shownId !== undefined) noteSellingShown();
  }, [shownId]);

  useEffect(() => {
    if (shownId === undefined || inlineHeld() === shownId) return;
    holdInline(shownId);
    sendOfferEvent(shownId, 'shown', 'ai_limit');
    void db
      .transaction('rw', db.meta, async () => {
        await setMeta('offerNotes', noteInlineMention(await getMeta('offerNotes'), new Date(serverNow())));
      })
      .catch(() => undefined);
  }, [shownId]);

  if (!shows) return null;
  const closes = new Date(offer.closesAt);
  const zone = zoneNameIfOther(accountZone);
  const until = momentEndShort(closes);
  return (
    <p className={styles.line}>
      {t('moment.inline', {
        amount: words.first,
        until: zone === undefined ? until : t('countdown.moment.zone', { when: until, zone }),
      })}
    </p>
  );
}
